from itertools import combinations

def can_cover_triangle(circles, triangle_sides):
    for sides in combinations(triangle_sides, 2):
        for circle in circles:
            if not circle[0] < sides[0] < circle[1] and not circle[0] < sides[1] < circle[1]:
                return False
    return True

def circles_needed(triangle_sides):
    sides = sorted(triangle_sides)
    min_circles = 0
    while not can_cover_triangle(min_circles, sides):
        min_circles += 1
    return min_circles

# Sides of the triangle
